# ==============================================================================
# Hattrick specialty icons (small, transparent PNGs made from the user's own icon images; ~2 KB each).
# They are CSS masks, so they take the colour of the text around them (dark and light theme).
#   CSS               -> added once per page by shell.apply_theme()
#   spec_select(sel)   -> icons in a Specialty dropdown
#   player_select(sel, specs_by_label) -> icon after the player's name in a player picker
#   table_specs(table, name_field, spec_field) -> icon after the name (and in the Specialty column) of a table
# ==============================================================================
import json
from urllib.parse import quote

ICONS = {
"Resilient": "data:image/png;base64,",
"Support": "data:image/png;base64,",
"Head": "data:image/png;base64,",
"Powerful": "data:image/png;base64,",
"Quick": "data:image/png;base64,",
"Technical": "data:image/png;base64,",
"Unpredictable": "data:image/png;base64,"
}

SPECS = list(ICONS)

CSS = ('<style>.tt-spec{display:inline-block;vertical-align:-3px;width:16px;height:16px;margin-left:6px;'
       'background:#F59E0B;opacity:1;-webkit-mask-size:contain;mask-size:contain;'
       '-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:center;mask-position:center}'
       '.tt-spec.tt-lead{margin-left:0;margin-right:8px;width:18px;height:18px}'
       + ''.join(f'.tt-spec-{k}{{-webkit-mask-image:url({v});mask-image:url({v})}}' for k, v in ICONS.items())
       + '</style>')


def has_icon(spec):
    return str(spec or '') in ICONS


def spec_select(sel):
    """A Specialty dropdown: icon before each specialty, in the list and in the field."""
    icon = ('<span v-if="[%s].includes(String(props.opt.label))" '
            ':class="\'tt-spec tt-lead tt-spec-\' + props.opt.label"></span>') % ','.join(f"'{k}'" for k in ICONS)
    sel.add_slot('option', '<q-item v-bind="props.itemProps"><q-item-section><q-item-label>'
                 + icon + '<span v-else style="display:inline-block;width:26px"></span>{{ props.opt.label }}'
                 '</q-item-label></q-item-section></q-item>')
    sel.add_slot('selected-item', '<span>' + icon + '{{ props.opt.label }}</span>')
    return sel


def player_select(sel, specs_by_label, selected=True, value_specs=None, short=False):
    """A player picker whose labels look like 'Name (NCD, 22)': icon after the name.
    specs_by_label = {label: specialty} (players without one can be left out).
    selected=False is for pickers you can type in: they show the chosen player the same way
    (value_specs is kept for older calls and not needed anymore)."""
    m = {str(k): str(v) for k, v in (specs_by_label or {}).items() if has_icon(v)}
    js = "JSON.parse(decodeURIComponent('" + quote(json.dumps(m, ensure_ascii=False), safe='') + "'))"
    body = ('<template v-for="M in [' + js + ']">'
            '<span>{{ String(props.opt.label).split(\' (\')[0] }}</span>'
            '<span v-if="M[props.opt.label]" :class="\'tt-spec tt-spec-\' + M[props.opt.label]"></span>'
            '<span v-if="String(props.opt.label).includes(\' (\')" style="opacity:.6">'
            ' ({{ String(props.opt.label).split(\' (\').slice(1).join(\' (\') }}</span></template>')
    sel.add_slot('option', '<q-item v-bind="props.itemProps"><q-item-section><q-item-label>' + body
                 + '</q-item-label></q-item-section></q-item>')
    if not selected:
        # a picker you can type in: show the chosen player like the other pickers (name, then icon)
        # and keep the input empty until you start typing
        sel.props(remove='hide-selected fill-input')
    if short:   # the chosen player as 'J. Surname' (the list keeps the full names)
        body_sel = body.replace("{{ String(props.opt.label).split(\' (\')[0] }}",
                                "{{ ((n) => { const p = n.split(' '); return (p.length > 1 && !n.startsWith('-')) ? p[0][0] + '. ' + p.slice(1).join(' ') : n })"
                                "(String(props.opt.label).split(' (')[0]) }}")
        sel.add_slot('selected-item', '<span>' + body_sel + '</span>')
    else:
        sel.add_slot('selected-item', '<span>' + body + '</span>')
    return sel


def table_specs(table, name_field='Speler', spec_field='Specialiteit', spec_column=True):
    """Icon after the player's name; with spec_column also before the text in the Specialty column."""
    ok = '[' + ','.join(f"'{k}'" for k in ICONS) + ']'
    table.add_slot(f'body-cell-{name_field}',
                   '<q-td :props="props">{{ props.value }}'
                   f'<span v-if="{ok}.includes(String(props.row[\'{spec_field}\']))" '
                   f':class="\'tt-spec tt-spec-\' + props.row[\'{spec_field}\']"></span></q-td>')
    if spec_column:
        table.add_slot(f'body-cell-{spec_field}',
                       '<q-td :props="props">'
                       f'<span v-if="{ok}.includes(String(props.value))" '
                       ':class="\'tt-spec tt-lead tt-spec-\' + props.value" style="width:15px;height:15px"></span>'
                       '{{ props.value }}</q-td>')
    return table